package com.faijan.interviewhub.config;

import com.faijan.interviewhub.entity.Question;
import com.faijan.interviewhub.repository.QuestionRepository;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import java.util.List;

@Configuration
public class PracticeQuestionSeeder {
    @Bean CommandLineRunner seedPracticeQuestions(QuestionRepository repo) {
        return args -> {
            List<Question> samples = List.of(
                q("Which collection guarantees insertion order and allows duplicates?","Java","Collections","Beginner","List", "Set", "Map", "Queue","A","A List preserves positional order and permits duplicate elements."),
                q("Which map implementation is generally used for fast key-based lookup without ordering guarantees?","Java","Collections","Beginner","TreeMap","HashMap","LinkedHashMap","EnumMap","B","HashMap provides expected constant-time get and put under a well-distributed hash function."),
                q("What does the volatile keyword guarantee in Java?","Java","Multithreading","Advanced","Atomicity of all operations","Visibility of writes across threads","Mutual exclusion","Thread termination","B","Volatile establishes visibility and ordering guarantees, but does not make compound operations such as count++ atomic."),
                q("Which method starts a new thread of execution?","Java","Multithreading","Beginner","run()","execute()","start()","submit()","C","Thread.start() schedules a new thread; calling run() directly executes on the current thread."),
                q("Which Spring annotation marks a class as a REST controller?","Spring Boot","Spring MVC","Beginner","@Service","@RestController","@Repository","@Configuration","B","@RestController combines @Controller and @ResponseBody so handler return values are written to the response body."),
                q("Which Spring component acts as the front controller in Spring MVC?","Spring Boot","Spring MVC","Beginner","DispatcherServlet","ViewResolver","HandlerAdapter","Model","A","DispatcherServlet receives requests and coordinates handler mapping, invocation and response processing."),
                q("What is the default scope of a Spring bean?","Spring Boot","Spring Core","Beginner","Prototype","Request","Session","Singleton","D","Singleton is the default: one bean instance per bean definition per Spring IoC container."),
                q("Which annotation is commonly used to inject a configuration value?","Spring Boot","Configuration","Beginner","@Value","@Bean","@Import","@Primary","A","@Value injects a property or expression into a Spring-managed bean."),
                q("Which interface is the usual base for CRUD and paging repositories in Spring Data JPA?","Spring Data JPA","Repositories","Beginner","CrudRepository","JpaTransactionManager","EntityManagerFactory","JdbcTemplate","A","CrudRepository supplies common create, read, update and delete operations; PagingAndSortingRepository adds paging and sorting."),
                q("Which annotation marks the owning side of a JPA relationship join column?","Hibernate","JPA Mapping","Intermediate","@JoinColumn","@MappedSuperclass","@Embeddable","@Transient","A","@JoinColumn defines the foreign-key column used by an association mapping."),
                q("Which HTTP method is intended for a partial update?","REST API","HTTP Methods","Beginner","GET","POST","PATCH","TRACE","C","PATCH applies a partial modification; PUT is generally used to replace a resource representation."),
                q("What does HTTP status 201 indicate?","REST API","HTTP Status Codes","Beginner","Accepted","Created","No Content","Not Modified","B","201 Created indicates that the request created a resource, commonly returned after POST."),
                q("Which SQL clause filters groups after aggregation?","MySQL","SQL","Beginner","WHERE","ORDER BY","HAVING","LIMIT","C","HAVING filters grouped rows after aggregate expressions have been evaluated."),
                q("Which index structure is commonly used by MySQL InnoDB for primary keys?","MySQL","Indexes","Intermediate","Hash index","Clustered B+ tree","Bitmap index","Heap index","B","InnoDB stores table rows in the clustered primary-key B+ tree."),
                q("What is a cache miss?","Redis","Caching","Beginner","Key exists in cache","Requested key is absent from cache","Cache is cleared","A write is rejected","B","A cache miss occurs when the requested item is not found in the cache and must be loaded elsewhere."),
                q("Which Kafka component reads records from a topic?","Kafka","Messaging","Beginner","Producer","Consumer","Broker controller","Partitioner","B","A Kafka consumer polls records from topic partitions and tracks offsets."),
                q("What is the main purpose of a Kafka consumer group?","Kafka","Messaging","Intermediate","Encrypt messages","Coordinate parallel consumption of partitions","Create topics automatically","Compress producer payloads","B","Consumers in one group share partitions so each partition is assigned to one group member at a time."),
                q("Which Spring Security concept checks whether an authenticated user may perform an action?","Spring Security","Authorization","Beginner","Authentication","Authorization","Serialization","Bean scope","B","Authorization evaluates permissions and roles after the identity has been authenticated."),
                q("What does a JWT signature primarily provide?","Spring Security","JWT","Intermediate","Confidentiality of payload","Integrity and authenticity of claims","Automatic token revocation","Password encryption","B","A valid signature allows a verifier to detect changes and verify the token issuer; JWT payloads are not encrypted by default."),
                q("Which design principle helps a microservice own its data?","Microservices","Architecture","Intermediate","Shared database for every service","Database per service","Single global schema with cross-service writes","Direct table access","B","Database-per-service encourages independent ownership and reduces coupling between services."),
                q("Which resilience pattern limits repeated calls to a failing dependency?","Microservices","Resilience","Advanced","Circuit breaker","Object pool","Builder","Repository","A","A circuit breaker temporarily stops calls to a failing dependency to allow recovery and prevent cascading failures."),
                q("Which contract must be preserved when overriding equals() and hashCode()?","Java","Object Contract","Intermediate","Equal objects must have equal hash codes","Unequal objects must have different hash codes","hashCode must be unique","equals must compare object identity","A","If two objects are equal according to equals(), they must return the same hash code. The reverse is not required."),
                q("Why are Java String objects immutable?","Java","Core Java","Beginner","They can never be compared","Their value cannot change after creation","They are always stored on the stack","They cannot be serialized","B","String immutability supports safe sharing, predictable hashing and string-pool reuse."),
                q("Which statement about checked exceptions is correct?","Java","Exception Handling","Intermediate","They must be caught or declared","They can only occur in constructors","They are always JVM errors","They cannot be subclassed","A","Checked exceptions are verified by the compiler and must be caught or declared in the method signature."),
                q("Which Java interface represents a function with one abstract method?","Java","Functional Programming","Beginner","Serializable","Runnable only","Functional interface","Cloneable","C","A functional interface has exactly one abstract method and can be implemented with a lambda expression."),
                q("What does Stream.map() do?","Java","Streams","Beginner","Filters elements","Transforms each element","Sorts the stream","Collects results","B","map applies a transformation function to each element and produces a stream of transformed values."),
                q("Which annotation enables declarative transaction boundaries on Spring methods or classes?","Spring Boot","Transactions","Intermediate","@Transactional","@Bean","@Primary","@Profile","A","@Transactional lets Spring manage transaction boundaries through its transaction infrastructure and proxies."),
                q("What does @SpringBootApplication combine?","Spring Boot","Auto Configuration","Beginner","@Component only","@Configuration, @EnableAutoConfiguration and @ComponentScan","@Service and @Repository","@Controller and @RestController","B","The annotation combines configuration, auto-configuration and component scanning for a typical Boot application."),
                q("Which annotation binds external configuration properties to a typed Java object?","Spring Boot","Configuration","Intermediate","@PropertySource only","@ConfigurationProperties","@Autowired","@ImportResource","B","@ConfigurationProperties maps a group of external properties onto a structured bean, including relaxed binding."),
                q("What is the purpose of @Qualifier when several beans share one interface?","Spring Boot","Dependency Injection","Intermediate","To create a new bean","To select a specific bean candidate","To disable component scanning","To make a bean prototype-scoped","B","@Qualifier narrows dependency injection to the bean identified by the qualifier value."),
                q("Which annotation binds a URI template value such as /users/{id} to a controller parameter?","Spring Boot","Spring MVC","Beginner","@RequestBody","@RequestParam","@PathVariable","@ResponseStatus","C","@PathVariable binds a path segment variable from the request URI to a handler method parameter."),
                q("What does @RequestBody do in Spring MVC?","Spring Boot","Spring MVC","Beginner","Reads a URI path segment","Deserializes the request body into an object","Writes only HTTP headers","Starts a transaction","B","@RequestBody uses an HTTP message converter, commonly Jackson, to deserialize the request body."),
                q("What is the primary purpose of EntityManager in JPA?","Hibernate","JPA","Intermediate","Manage the persistence context and entity operations","Create HTTP sessions","Configure Redis clients","Start Kafka consumers","A","EntityManager manages entity lifecycle operations and the persistence context for a unit of work."),
                q("What does FetchType.LAZY mean for a JPA association?","Hibernate","Fetching","Intermediate","Always load it with the parent","Load it when accessed, subject to persistence-context availability","Never load it","Load it only during INSERT","B","Lazy fetching defers loading the association until it is accessed; accessing it outside an open persistence context can fail."),
                q("What does orphanRemoval=true do on a JPA relationship?","Hibernate","Entity Lifecycle","Advanced","Deletes the parent on update","Removes child rows when they are orphaned from the relationship","Disables cascading","Prevents all deletes","B","Orphan removal deletes a child entity when it is removed from the parent relationship, subject to the mapping and transaction."),
                q("Which join returns every row from the left table and matching rows from the right table?","MySQL","Joins","Beginner","INNER JOIN","RIGHT JOIN","LEFT JOIN","CROSS JOIN","C","LEFT JOIN keeps all left-table rows and fills right-table columns with NULL when there is no match."),
                q("Which ACID property means a transaction is all-or-nothing?","MySQL","Transactions","Beginner","Consistency","Atomicity","Isolation","Durability","B","Atomicity ensures all operations in a transaction succeed together or the transaction is rolled back."),
                q("What is a common trade-off of adding database indexes?","MySQL","Indexes","Intermediate","Faster writes with no storage cost","More storage and write overhead in exchange for faster reads","Indexes remove the need for constraints","Indexes guarantee every query uses them","B","Indexes can improve lookup and sorting performance but consume storage and add maintenance work to writes."),
                q("What does a Redis key TTL control?","Redis","Key Expiration","Beginner","Maximum key size","Time until a key expires automatically","Number of clients","Memory compression","B","TTL is the remaining lifetime of a key before Redis expires it automatically."),
                q("What is cache invalidation?","Redis","Caching","Intermediate","Compressing cached values","Removing or refreshing stale cached data","Encrypting database tables","Increasing a key TTL","B","Cache invalidation ensures cached values do not remain stale after the underlying source data changes."),
                q("What is a Kafka partition?","Kafka","Topics and Partitions","Beginner","A consumer password","An ordered log segment within a topic","A schema registry","A broker controller","B","A partition is an ordered append-only log; a topic can be split across partitions for parallelism."),
                q("Within a Kafka partition, what does an offset identify?","Kafka","Consumer Offsets","Beginner","The broker IP address","A record position in the partition log","The consumer group name","A topic encryption key","B","An offset is a position identifier for a record within a particular partition."),
                q("Which ordering guarantee does Kafka provide by default?","Kafka","Ordering","Advanced","Global order across all topics","Order within a single partition","Order across every partition in a topic","Order across all brokers","B","Records are read in append order within one partition; multiple partitions do not provide a global total order."),
                q("What does idempotent mean for an HTTP operation?","REST API","HTTP Semantics","Intermediate","Repeated identical requests have the same intended effect as one request","The response is always empty","The request never changes data","The request must use POST","A","An idempotent method has the same intended server effect when the same request is repeated."),
                q("Which HTTP status code indicates the requested resource was not found?","REST API","HTTP Status Codes","Beginner","400","401","404","500","C","404 Not Found indicates that the server cannot find the requested resource representation."),
                q("What does authentication establish?","Spring Security","Identity","Beginner","What a user is allowed to do","Who a user or client is","How a database is indexed","Whether a cache is stale","B","Authentication verifies the claimed identity; authorization determines what that identity is permitted to do."),
                q("Why should a JWT access token have an expiration time?","Spring Security","JWT","Intermediate","To make the payload secret","To limit the time a stolen token remains usable","To make it reusable forever","To avoid signature validation","B","An expiration bounds token lifetime and reduces the exposure window if a token is compromised."),
                q("What is the purpose of an API gateway in a microservices system?","Microservices","API Gateway","Intermediate","Store all service data","Provide a common entry point for routing and cross-cutting policies","Replace every service database","Guarantee exactly-once delivery","B","A gateway can centralize routing, authentication integration, rate limits and other cross-cutting concerns."),
                q("What is the Saga pattern used for?","Microservices","Distributed Transactions","Advanced","Local in-memory caching","Coordinating a distributed business transaction through steps and compensations","Compiling Java code","Partitioning a Kafka topic","B","A Saga coordinates local transactions across services and uses compensating actions when a later step fails."),
                q("What is the main difference between a container and a virtual machine?","Docker","Containers","Beginner","Containers include a separate guest kernel by default","Containers share the host kernel while VMs run a guest OS","VMs cannot run Linux","Containers always use more memory","B","Containers isolate processes while sharing the host kernel; virtual machines virtualize hardware and run a guest operating system."),
                q("Why should a Docker application run as a non-root user?","Docker","Container Security","Intermediate","To improve network speed","To reduce privileges if the process is compromised","To avoid container layers","To make images larger","B","Running with least privilege limits the impact of application vulnerabilities inside the container.")
            );
            for (Question question : samples) if (!repo.existsByTitleIgnoreCase(question.getTitle())) repo.save(question);
        };
    }
    private Question q(String title,String tech,String category,String difficulty,String a,String b,String c,String d,String answer,String explanation){return new Question(title,tech,category,difficulty,explanation,null,a,b,c,d,answer);}
}
